using System;using System.IO;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
namespace ParkingLotEnvironment.CloudPilot {public static class PorterMeshRefresh {
 [Serializable]class Record{public string name,file;public int vertexCount,indexCount,material;}
 [Serializable]class Model{public Record[] meshes;}
 public static void Apply(){string w=ContextBuilder.W;var data=JsonUtility.FromJson<Model>(File.ReadAllText(w+"/PorterData/porter.json"));foreach(var item in data.meshes){var mesh=new Mesh{name="Porter_"+item.name,indexFormat=IndexFormat.UInt32};var vv=new Vector3[item.vertexCount];var nn=new Vector3[item.vertexCount];var uv=new Vector2[item.vertexCount];var indices=new int[item.indexCount];using(var r=new BinaryReader(File.OpenRead(w+"/PorterData/"+item.file))){for(int i=0;i<vv.Length;i++){vv[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());nn[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());}for(int i=0;i<indices.Length;i++)indices[i]=(int)r.ReadUInt32();}mesh.vertices=vv;mesh.normals=nn;mesh.uv=uv;mesh.triangles=indices;mesh.RecalculateBounds();mesh.RecalculateTangents();var asset=AssetDatabase.LoadAssetAtPath<Mesh>(w+"/Porter_"+item.name+".asset");if(!asset)throw new Exception("Owned Porter mesh missing");EditorUtility.CopySerialized(mesh,asset);EditorUtility.SetDirty(asset);UnityEngine.Object.DestroyImmediate(mesh);}AssetDatabase.SaveAssets();}
}}
